solutions.naive:
from typing import List

class Solution:
    def findCircleNum(self, isConnected: List[List[int]]) -> int:
        # DFS scans matrix rows for neighbors.
        n = len(isConnected); seen = set()
        def dfs(i):
            seen.add(i)
            for j in range(n):
                if isConnected[i][j] and j not in seen:
                    dfs(j)
        ans = 0
        for i in range(n):
            if i not in seen:
                ans += 1; dfs(i)
        return ans

